"""Build a self-contained offline demo from the disposable WordPress view export."""
import base64
import json
import re
from pathlib import Path

root = Path(__file__).resolve().parents[1]
data = json.loads(Path('/tmp/icpa-platform-views.json').read_text())
for key, value in list(data.items()):
    if not isinstance(value, str):
        continue
    for name in ('community', 'education', 'health'):
        svg = base64.b64encode((root / f'icpa-fundraising/assets/{name}.svg').read_bytes()).decode()
        value = re.sub(r'https?://localhost[^\"\s]*/icpa-fundraising/assets/' + name + r'\.svg', lambda _: f'data:image/svg+xml;base64,{svg}', value)
    data[key] = value
css = (root / 'icpa-fundraising/assets/platform.css').read_text() + (root / 'icpa-fundraising/assets/fee-settings.css').read_text()
geometry = base64.b64encode((root / 'icpa-fundraising/assets/geometry.svg').read_bytes()).decode()
css = css.replace('url("geometry.svg")', f'url("data:image/svg+xml;base64,{geometry}")')
for name in ('Regular', 'SemiBold', 'Bold'):
    font = base64.b64encode((root / f'icpa-fundraising/assets/fonts/Poppins-{name}.ttf').read_bytes()).decode()
    css = css.replace(f'url("fonts/Poppins-{name}.ttf")', f'url("data:font/ttf;base64,{font}")')
plugin_js = (root / 'icpa-fundraising/assets/platform.js').read_text() + (root / 'icpa-fundraising/assets/fee-settings.js').read_text()
payload = json.dumps(data).replace('</', '<\\/')
shell = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ICPA Fundraising — interactive demo</title><style>
body{margin:0;background:#fff}#app{font-family:"ICPA Poppins",Poppins,Arial,sans-serif;max-width:1200px;margin:0 auto;padding:0 28px}.demo-bar{font:12px/1.5 system-ui,sans-serif;background:#173b30;color:#fff;padding:10px 24px;display:flex;justify-content:space-between;align-items:center;gap:12px}.demo-bar strong{font-weight:650}.demo-shortcuts{display:flex;gap:14px;flex-wrap:wrap}.demo-shortcuts button{font:inherit;color:#fff;background:none;border:0;cursor:pointer;padding:4px}.demo-shortcuts button:focus-visible{outline:2px solid #fff}.demo-toast{position:fixed;left:50%;bottom:24px;transform:translateX(-50%);background:#173b30;color:#fff;padding:18px 22px;border-radius:12px;font:14px/1.6 system-ui,sans-serif;box-shadow:0 8px 40px #0003;max-width:560px;width:calc(100% - 40px);z-index:20}.demo-toast[hidden]{display:none}.demo-toast button{color:white;background:none;border:0;float:right;font-size:20px;cursor:pointer;margin-left:15px}@media(max-width:650px){.demo-bar{align-items:flex-start;flex-direction:column;padding:10px 18px}.demo-shortcuts{gap:12px}}
.demo-admin *{box-sizing:border-box}.demo-admin{overflow-wrap:anywhere;font:13px/1.6 Arial,sans-serif;color:#1d2327;background:#f0f0f1;padding:24px;margin:20px 0}.demo-admin h1{font-size:25px;font-weight:400}.demo-admin h2{font-size:20px;margin-top:30px}.demo-admin .form-table{width:100%;border-collapse:collapse}.demo-admin .form-table th{width:240px;text-align:left;vertical-align:top;padding:16px 15px 16px 0}.demo-admin .form-table td{padding:16px 0}.demo-admin input:not([type=checkbox]):not([type=hidden]),.demo-admin select{font:inherit;padding:6px 9px;max-width:100%;border:1px solid #8c8f94;background:white;border-radius:4px}.demo-admin .regular-text{width:350px}.demo-admin code{overflow-wrap:anywhere}.demo-admin .button{display:inline-block;padding:7px 14px;border:1px solid #2271b1;border-radius:3px;background:#fff;color:#2271b1;cursor:pointer}.demo-admin .button-primary{background:#2271b1;color:white}.demo-admin .description{color:#646970;font-size:12px}.demo-admin a{color:#2271b1}.demo-admin .notice{border-left:4px solid #00a32a;padding:4px 16px;background:#fff}@media(max-width:650px){.demo-admin{padding:18px}.demo-admin .form-table,.demo-admin .form-table tbody{display:block;width:100%;max-width:100%}.demo-admin .form-table tr,.demo-admin .form-table th,.demo-admin .form-table td{display:block;width:100%;padding:5px 0}.demo-admin .form-table tr{margin:18px 0}.demo-admin input{max-width:100%}}
CSS
</style></head><body><div class="demo-bar"><strong>WordPress plugin preview · Sample data · No payments · Demo account: Amina</strong><nav class="demo-shortcuts" aria-label="Preview pages"><button data-view="donate">General donations</button><button data-view="browse">Discover</button><button data-view="campaign0">Campaign</button><button data-view="start">Start a fundraiser</button><button data-view="account">My account</button><button data-view="settings">Settings</button><button data-view="recurring_settings">Recurring settings</button></nav></div><div id="app"></div><div class="demo-toast" role="status" hidden><button aria-label="Dismiss message" id="dismiss-toast">×</button><span id="toast-text"></span></div><script>
const views=PAYLOAD;
const app=document.getElementById('app');let current='browse';let draftTitle='';
function notify(text){document.getElementById('toast-text').textContent=text;document.querySelector('.demo-toast').hidden=false;}
document.getElementById('dismiss-toast').addEventListener('click',()=>document.querySelector('.demo-toast').hidden=true);
function render(view){current=Object.prototype.hasOwnProperty.call(views,view)&&typeof views[view]==='string'?view:'browse';app.innerHTML=views[current];document.querySelectorAll('.icpa-test-notice').forEach(n=>n.textContent='Sample campaigns and donation totals · Preview only — no real payments.');if(current==='account'&&draftTitle){const sections=app.querySelectorAll('.icpa-account-section');const row=document.createElement('div');row.className='icpa-organiser-row';const text=document.createElement('strong');text.textContent=draftTitle;const status=document.createElement('span');status.className='icpa-status';status.textContent='Awaiting ICPA review (demo)';row.append(text,status);sections[1].append(row);}window.scrollTo(0,0);}
function routeFor(href){try{const url=new URL(href,'http://localhost');for(const [key,value] of Object.entries(views.urls)){const match=new URL(value);if(url.pathname===match.pathname&&url.searchParams.get('page_id')===match.searchParams.get('page_id')&&url.searchParams.get('icpa_campaign')===match.searchParams.get('icpa_campaign'))return key;}}catch{}return null;}
function filterCards(cause,search){let shown=0;app.querySelectorAll('.icpa-card').forEach(card=>{const tag=card.querySelector('.icpa-tag').textContent.toLowerCase();const show=(!cause||tag===cause.toLowerCase())&&(!search||card.textContent.toLowerCase().includes(search.toLowerCase()));card.hidden=!show;card.style.display=show?'':'none';if(show)shown++;});let empty=app.querySelector('.demo-no-results');if(!empty){empty=document.createElement('p');empty.className='demo-no-results icpa-info';empty.textContent='No matching campaigns. Try another cause or search.';app.querySelector('.icpa-grid').after(empty);}empty.hidden=shown>0;}
document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){e.preventDefault();render(view.dataset.view);return;}const a=e.target.closest('a');if(!a)return;e.preventDefault();if(a.getAttribute('href')==='#icpa-discover'){document.getElementById('icpa-discover').scrollIntoView({behavior:'smooth'});return;}if(a.closest('.icpa-filters')){const url=new URL(a.getAttribute('href'),'http://localhost');const cause=url.searchParams.get('icpa_cause')||'';app.querySelectorAll('.icpa-filters a').forEach(link=>{link.classList.toggle('is-active',link===a);if(link===a)link.setAttribute('aria-current','true');else link.removeAttribute('aria-current');});filterCards(cause,app.querySelector('[name=icpa_search]').value);return;}const route=routeFor(a.href);if(route){render(route);return;}notify('Preview only. On your WordPress site, this opens the real account or campaign page.');});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target;if(form.matches('.icpa-search')){const cause=app.querySelector('.icpa-filters .is-active');const category=cause&&cause.textContent.trim()!=='All causes'?cause.textContent.trim():'';filterCards(category,form.querySelector('[name=icpa_search]').value);return;}if(form.matches('.icpa-donation-form')){const amount=Number(form.querySelector('[name=amount]').value);notify('Demo only: '+new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(amount)+' would open ICPA’s Square checkout. No payment has been made.');return;}if(form.matches('.icpa-recurring-form')){notify('Demo only: '+form.dataset.recurringPrice+' would repeat '+form.querySelector('[name=giving_option]').value.toLowerCase()+' through Square until cancelled. No subscription or payment has been created.');return;}if(form.matches('.icpa-campaign-form')){draftTitle=form.querySelector('[name=title]').value;render('account');notify('Demo submission added to your account as awaiting ICPA review. This sample is kept only until you reload the preview.');return;}notify('WordPress settings preview only. Configure and save these settings in your real WordPress administration area.');});
PLUGIN_JS
render('donate');
</script></body></html>'''
output = shell.replace('CSS', css).replace('PAYLOAD', payload).replace('PLUGIN_JS', plugin_js).replace('#173b30', '#281c46')
(root / 'preview/fundraising-platform.html').write_text(output)
print('Built preview/fundraising-platform.html from WordPress-rendered views')
